function styleTopBanner(){const bar=document.querySelector('.playerbar');if(!bar)return;const senior=bar.querySelector('[data-senior-hub]');if(senior)senior.textContent='Senior Challenge';const friends=bar.querySelector('[data-live="hub"]');if(friends){friends.innerHTML=petNavArt('live')+'<span>Live friends</span>';friends.setAttribute('aria-label','Play live with friends')}const audio=bar.querySelector('.audio-settings>summary');if(audio)audio.textContent='Audio';const account=bar.querySelector('[data-player-account]');if(account)account.textContent=account.textContent.replace(/^☁\s*/,'')}
const bannerCloudLabel=updateCloudLabel;updateCloudLabel=function(){bannerCloudLabel();const b=document.querySelector('.playerbar [data-player-account]');if(b)b.textContent=b.textContent.replace(/^☁\s*/,'')};
async function headerGoHome(){if(live){await leaveLiveRoom();return}clearQuestionClock();closeModal();quiz=null;activeInvite=null;friendDraft=false;practiceDraft=false;liveDraft=false;resetControls();navigate('home')}
function headerPlay(){if(live){if(live.battleStarted){closeModal();document.querySelector('#arena')?.focus()}else drawLiveLobby();return}if(game?.prepared&&game.hp>0&&game.time>0&&!quiz){closeModal();game.paused=false;resetControls();last=performance.now();document.querySelector('#arena')?.focus();return}clearQuestionClock();closeModal();quiz=null;activeInvite=null;friendDraft=false;practiceDraft=false;liveDraft=false;if(game||currentPage!=='home')navigate('home');chooseBattleTopics()}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.hasAttribute('data-header-home'))headerGoHome();else if(b.hasAttribute('data-header-play'))headerPlay()});
styleTopBanner();

const setupHandControls=personalHub;personalHub=function(){setupHandControls();document.querySelector('.setup-actions')?.insertAdjacentHTML('beforebegin',handSwitchHTML());refreshHandSwitch()};

function refreshPlayerNickname(){const name=document.querySelector('[data-player-nickname]');if(name){name.textContent=cleanName(profile.playerName)||'New player';name.title=cleanName(profile.playerName)||'Set your nickname below'}}
const nicknameUpdateBar=updateBar;updateBar=function(){nicknameUpdateBar();refreshPlayerNickname()};
const nicknameHome=home;home=function(){let html=nicknameHome();if(cleanName(profile.playerName))html=html.replace(/<section class="player-card player-identity">[\s\S]*?<\/section>/,'');return html};
const nicknameSetup=personalHub;personalHub=function(){nicknameSetup();document.querySelector('.setup-actions')?.insertAdjacentHTML('beforebegin',`<section class="account-details"><div class="account-heading"><span class="account-emblem" aria-hidden="true">${petNavArt('heroes')}</span><div><h3>Account details</h3><p>Your nickname is how friends recognise you.</p></div></div><form id="nickname-settings"><label for="setup-nickname">Player nickname</label><div class="nickname-edit"><input id="setup-nickname" name="nickname" maxlength="20" required autocomplete="off" value="${safeText(profile.playerName)}" placeholder="Choose your nickname"><button class="primary" type="submit">${profile.playerName?'Change nickname':'Save nickname'}</button></div><p class="nickname-status" role="status">Use a nickname, rather than your full name.</p></form></section>`)};
document.addEventListener('submit',event=>{if(event.target.id!=='nickname-settings')return;event.preventDefault();const name=cleanName(document.querySelector('#setup-nickname')?.value);if(!name){toast('Enter a nickname first.');return}if(live){toast('Change your nickname after leaving the live room.');return}profile.playerName=name;save();if(currentPage==='home'&&!game)page.innerHTML=home();document.querySelector('.nickname-status').textContent='Nickname saved. Your friends will see this name in your next room.';event.target.querySelector('button').textContent='Change nickname'});
refreshPlayerNickname();
if(currentPage==='home'&&!game&&!live&&!quiz)page.innerHTML=home();

const distinctProgressArt=petNavArt;petNavArt=function(kind){if(kind!=='progress')return distinctProgressArt(kind);return `<span class="nav-badge nav-badge-progress" aria-hidden="true"><svg viewBox="0 0 80 80"><g stroke="#193b53" stroke-width="3" stroke-linejoin="round" stroke-linecap="round"><rect x="8" y="43" width="14" height="27" rx="4" fill="#8eccee"/><rect x="29" y="32" width="14" height="38" rx="4" fill="#a9a0ef"/><rect x="50" y="21" width="14" height="49" rx="4" fill="#74ddbd"/><path d="m10 32 19-14 12 4 17-12" fill="none" stroke="#d8fff2" stroke-width="4"/><path d="m59 4 5 9 10 2-7 7 1 10-9-5-9 5 2-10-8-7 10-2Z" fill="#ffe392"/><path d="M7 72h61" stroke="#a9d6e7"/></g></svg></span>`};
refreshPetNavigation();
